 p_id=>wwv_flow_imp.id(24896409062473562588)
,p_plug_name=>'Catalog Information'
,p_static_id=>'catalog-information'
,p_region_template_options=>'#DEFAULT#:t-ContentBlock--h1:t-ContentBlock--hideHeader js-addHiddenHeadingRoleDesc'
,p_plug_template=>2323592004483952560
,p_plug_display_sequence=>80
,p_plug_item_display_point=>'ABOVE'
,p_location=>null
,p_plug_source=>'This catalog is domain-neutral and self-contained. Pages use portable sample data and document design intent through APEX metadata rather than visible instructional content.'
,p_attributes=>wwv_flow_t_plugin_attributes(wwv_flow_t_varchar2(
  'expand_shortcuts', 'N',
  'output_as', 'HTML')).to_clob
);
